/// A page on the app's own ground, composed exactly as the
/// shipped pushed pages compose it (ember_settings.dart's
/// _emberPageRoute / automation_pages.dart's _pageShell):
/// the backdrop inside a Scaffold body over Ember.bg.
/// [banded] mirrors the shell's ground for the surface under
/// capture (build 2145, UI-review fix A3): the shell bands
/// every non-home tab and the aether text homes, so the
/// servers / accounts / settings / engine captures wear the
/// banded ground too; the DPI Lab's pushed page keeps the
/// full map.
Widget _ground(Widget child, {bool banded = false}) => MaterialApp(
  debugShowCheckedModeBanner: false,
  theme: ThemeData(
    brightness: Brightness.dark,
    scaffoldBackgroundColor: Ember.bg,
  ),
  localizationsDelegates: AppLocalizations.localizationsDelegates,
  supportedLocales: AppLocalizations.supportedLocales,
  home: Scaffold(
    backgroundColor: Ember.bg,
    body: EmberBackground(banded: banded, child: SafeArea(child: child)),
  ),
);

/// The test harness's built-in font draws every glyph as a
/// same-width box — unreadable, and wide enough to overflow rows
/// that fit easily on a phone. Load the real fonts the phone
/// renders with — Roboto and Material Icons, both bundled in
/// the Flutter SDK's material_fonts artifact — under their
/// family names, so the captures carry real text, real icons
/// and real metrics. Liberation Sans is the fallback sans if
/// the SDK artifact is absent; if nothing is found, loading is
/// skipped and the captures degrade to the harness font.
Future<void> _loadRealFonts() async {
  Future<void> load(String family, List<String> files) async {
    if (!files.every((f) => File(f).existsSync())) return;
    final loader = FontLoader(family);
    for (final f in files) {
      final bytes = await File(f).readAsBytes();
      loader.addFont(
        Future.value(ByteData.view(Uint8List.fromList(bytes).buffer)),
      );
    }
    await loader.load();
  }

  final sdkFonts = [
    if (Platform.environment['FLUTTER_ROOT'] != null)
      '${Platform.environment['FLUTTER_ROOT']}/bin/cache/artifacts/material_fonts',
    '/home/hatch/workspace/ember-app/toolchain/flutter/bin/cache/artifacts/material_fonts',
  ];
  for (final dir in sdkFonts) {
    await load('Roboto', [
      '$dir/Roboto-Regular.ttf',
      '$dir/Roboto-Medium.ttf',
      '$dir/Roboto-Bold.ttf',
      '$dir/Roboto-Italic.ttf',
      '$dir/Roboto-BoldItalic.ttf',
    ]);
    await load('MaterialIcons', ['$dir/MaterialIcons-Regular.otf']);
  }
  await load('Roboto', const [
    '/usr/share/fonts/truetype/liberation/LiberationSans-Regular.ttf',
    '/usr/share/fonts/truetype/liberation/LiberationSans-Bold.ttf',
    '/usr/share/fonts/truetype/liberation/LiberationSans-Italic.ttf',
    '/usr/share/fonts/truetype/liberation/LiberationSans-BoldItalic.ttf',
  ]);
}

void main() {
  setUpAll(_loadRealFonts);

  testWidgets('shot: home (full shell, V2Ray mode)', (tester) async {
    wt.stillMotion(tester);
    _phone(tester);
    // The shell's engine controllers poll the 'app/android'
    // channel (the fake of build2054's page tests): every
    // engine stopped, everything else null — a fresh app.
    final messenger =
        TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger;
    messenger.setMockMethodCallHandler(
      const MethodChannel('app/android'),
      (call) async {
        if (call.method == 'xrayState') {
          return <String, Object?>{
            'running': false,
            'name': '',
            'sinceMs': 0,
            'up': 0,
            'down': 0,
            'coreRestarts': 0,
            'coreProblem': '',
            'chainUnderlay': false,
            'chainProblem': '',
            'awg': false,
            'awgConfig': '',
            'rotationGen': 0,
          };
        }
        return null;
      },
    );
    addTearDown(
      () => messenger.setMockMethodCallHandler(
        const MethodChannel('app/android'),
        null,
      ),
    );
    final core = CoreController(
      () async => wt.FakeApi(),
      pollInterval: const Duration(hours: 1),
    );
    await tester.pumpWidget(VpnApp(core: core, settings: AppSettings()));
    core.start();
    await tester.pump();
    await tester.pump(const Duration(milliseconds: 400));
    // Let real async work (the backdrop image decode) finish,
    // then settle a frame — goldens otherwise catch the shell
    // over a not-yet-decoded ground.
    await tester.runAsync(
      () => Future<void>.delayed(const Duration(milliseconds: 600)),
    );
    await tester.pump();
    await tester.pump(const Duration(milliseconds: 400));
    // Switch to the V2Ray engine from the chip rail.
    await tester.tap(find.text('V2Ray').first);
    await tester.pump();
    await tester.pump(const Duration(milliseconds: 400));
    await expectLater(
      find.byType(VpnApp),
      matchesGoldenFile('screenshots/ui-home.png'),
    );
    await tester.pumpWidget(const SizedBox());
    // Inside the body, as widget_test.dart does: the core's
    // restart timer must not outlive the test.
    core.dispose();
  });

  testWidgets('shot: mozilla accounts', (tester) async {
    wt.stillMotion(tester);
    _phone(tester);
    // Build 2145 (UI-review fix A5): this shot used to pump
    // the full shell in its default mode, so its golden was
    // the HOME screen — byte-identical to an old home
    // capture (build2121-home) — and the recomposed Mozilla
    // account surface was pictured by no golden at all. The
    // shot now renders the surface it names: EmberAccounts
    // in Mozilla mode over a dead core carrying one ready
    // sample account, on the banded ground the shell's
    // accounts tab wears (fix A3).
    final core = _deadCore();
    core.accounts = AccountList.fromJson({
      'accounts': [
        {
          'id': 'acc1',
          'name': 'Sample Account',
          'email': 'user@example.net',
          'position': 0,
          'enabled': true,
          'active': true,
          'status': 'ready',
          'usage': {
            'unlimited': false,
            'limit_bytes': 50 << 30,
            'remaining_bytes': 32 << 30,
          },
          'used_percent': 36.0,
          'has_password': true,
        },
      ],
      'switch_threshold_percent': 80.0,
    });
    await tester.pumpWidget(
      _ground(
        EmberAccounts(core: core, xray: _sampleXray(), v2ray: false),
        banded: true,
      ),
    );
    await tester.pump();
    await tester.pump(const Duration(milliseconds: 300));
    await expectLater(
      find.byType(MaterialApp),
      matchesGoldenFile('screenshots/ui-mozilla.png'),
    );
    await tester.pumpWidget(const SizedBox());
  });

  testWidgets('shot: DPI Lab', (tester) async {
    wt.stillMotion(tester);
    _phone(tester);
    final xray = _sampleXray();
    await tester.pumpWidget(_ground(DpiLabPage(xray: xray)));
    await tester.pump();
    await tester.pump(const Duration(milliseconds: 300));
    await expectLater(
      find.byType(MaterialApp),
      matchesGoldenFile('screenshots/ui-dpi-lab.png'),
    );
    await tester.pumpWidget(const SizedBox());
  });

  testWidgets('shot: V2Ray servers list', (tester) async {
    wt.stillMotion(tester);
    _phone(tester);
    final xray = _sampleXray();
    await tester.pumpWidget(
      _ground(
        EmberServers(
          core: _deadCore(),
          xray: xray,
          v2ray: true,
          onOpenAccounts: () {},
